import java.io._
import java.nio.file._
import java.util.concurrent.atomic._
import java.util.concurrent._
import scala.collection.mutable
import sun.misc.{Signal, SignalHandler}

object MonitoringAgent {
  private val uploadDir = Paths.get("/var/uploads")
  private val logFile = Paths.get("/var/log/agent/monitor.log")
  private val processingQueue = new LinkedBlockingQueue[Path](1000)
  private val activeUploads = new ConcurrentHashMap[String, UploadState]()
  private val shutdownRequested = new AtomicBoolean(false)
  private val drainComplete = new AtomicBoolean(false)

  case class UploadState(
    tempPath: Path,
    finalPath: Path,
    bytesWritten: AtomicLong,
    validated: AtomicBoolean,
    committed: AtomicBoolean
  )

  private val signalHandler: SignalHandler = new SignalHandler {
    override def handle(sig: Signal): Unit = {
      shutdownRequested.set(true)
      // Signal only sets the flag; drain happens in main thread
    }
  }

  private def drainQueue(): Unit = {
    val pending = new java.util.ArrayList[Path]()
    processingQueue.drainTo(pending)
    val iter = pending.iterator()
    while (iter.hasNext) {
      val path = iter.next()
      val uploadId = path.getFileName.toString
      if (validateUpload(uploadId)) {
        commitUpload(uploadId)
      } else {
        val state = activeUploads.get(uploadId)
        if (state != null) {
          Files.deleteIfExists(state.tempPath)
          activeUploads.remove(uploadId)
        }
      }
    }
    drainComplete.set(true)
  }

  private def commitUpload(uploadId: String): Unit = {
    val state = activeUploads.get(uploadId)
    if (state != null) {
      if (state.validated.get() && state.committed.compareAndSet(false, true)) {
        Files.move(state.tempPath, state.finalPath, StandardCopyOption.REPLACE_EXISTING)
        writeLog(s"Committed upload $uploadId (${state.bytesWritten.get()} bytes)")
      }
    }
  }

  private def validateUpload(uploadId: String): Boolean = {
    val state = activeUploads.get(uploadId)
    if (state == null) return false

    val content = Files.readAllBytes(state.tempPath)
    val hasValidHeader = content.length >= 4 && 
      content(0) == 0x89.toByte && content(1) == 'P'.toByte &&
      content(2) == 'N'.toByte && content(3) == 'G'.toByte

    val pathTraversalFree = !state.finalPath.toString.contains("..")
    val sizeOk = state.bytesWritten.get() <= 10 * 1024 * 1024

    val valid = hasValidHeader && pathTraversalFree && sizeOk
    state.validated.set(valid)
    valid
  }

  def handleUpload(uploadId: String, inputStream: InputStream, targetName: String): Either[String, Path] = {
    val sanitizedName = targetName.replaceAll("[^a-zA-Z0-9._-]", "_")
    // Sanitize uploadId to prevent path traversal into arbitrary locations.
    val sanitizedId = uploadId.replaceAll("[^a-zA-Z0-9._-]", "_")
    val tempBase = uploadDir.resolve(".tmp").toAbsolutePath.normalize()
    val tempPath = tempBase.resolve(sanitizedId).toAbsolutePath.normalize()
    val finalPath = uploadDir.resolve("committed").resolve(sanitizedName)

    // Ensure the resolved temp path stays within the intended temp directory.
    if (!tempPath.startsWith(tempBase)) {
      return Left("Invalid upload identifier")
    }

    val state = UploadState(
      tempPath = tempPath,
      finalPath = finalPath,
      bytesWritten = new AtomicLong(0),
      validated = new AtomicBoolean(false),
      committed = new AtomicBoolean(false)
    )

    activeUploads.put(sanitizedId, state)
    Files.createDirectories(tempPath.getParent)

    val out = new FileOutputStream(tempPath.toFile)
    try {
      val buffer = new Array[Byte](8192)
      var bytesRead = inputStream.read(buffer)
      while (bytesRead != -1 && !shutdownRequested.get()) {
        out.write(buffer, 0, bytesRead)
        state.bytesWritten.addAndGet(bytesRead)
        bytesRead = inputStream.read(buffer)
      }
      out.flush()
    } finally {
      out.close()
    }

    processingQueue.offer(tempPath)

    if (shutdownRequested.get()) {
      Left("Upload interrupted by shutdown")
    } else {
      if (validateUpload(sanitizedId)) {
        commitUpload(sanitizedId)
        Right(finalPath)
      } else {
        Files.deleteIfExists(tempPath)
        activeUploads.remove(sanitizedId)
        Left("Validation failed")
      }
    }
  }

  private def writeLog(message: String): Unit = {
    val writer = new FileWriter(logFile.toFile, true)
    try {
      writer.write(s"[${System.currentTimeMillis()}] $message\n")
    } finally {
      writer.close()
    }
  }

  def initialize(): Unit = {
    Signal.handle(new Signal("USR1"), signalHandler)
    Files.createDirectories(uploadDir.resolve(".tmp"))
    Files.createDirectories(uploadDir.resolve("committed"))
    writeLog("Monitoring agent initialized")
  }

  def main(args: Array[String]): Unit = {
    initialize()
    writeLog("Agent running, awaiting uploads...")
    // Main event loop
    while (!shutdownRequested.get()) {
      Thread.sleep(100)
    }
    // Drain happens safely in main thread after shutdown flag is set
    drainQueue()
    writeLog("Agent shutdown complete")
  }
}
